/**
 * BulkCreateResult
 *
 * Result of a bulk invoice creation (`POST /v1/companies/{company}/invoices/bulk-create`). `dry_run` reports the mode. In validate-only mode (`dry_run=true`) `results[]` carries the per-row classification `{index, status, errors[], warnings[]}` and nothing is persisted; in create mode (`dry_run=false`) only valid rows are created and `failures[]` carries the rows that were not created (identified by `index`). `total = successful + failed`.
 */
export type BulkCreateResult = {
    /**
     * Whether the operation ran in validate-only mode (no invoice was created).
     */
    dry_run: boolean;
    /**
     * Number of rows processed (`successful + failed`).
     */
    total: number;
    /**
     * Number of rows that validated successfully (`dry_run=true`) or were created (`dry_run=false`).
     */
    successful: number;
    /**
     * Number of rows that were invalid or could not be created. Equals `failures` length in create mode.
     */
    failed: number;
    /**
     * Per-row classification of validate-only mode (`dry_run=true`). Empty in create mode.
     */
    results: Array<{
        /**
         * 0-based position of the row within the batch.
         */
        index: number;
        /**
         * Row status: `valid` (would be created without error) or `invalid` (has blocking errors).
         */
        status: string;
        /**
         * Per-field blocking issues of the row. Empty when the row is valid.
         */
        errors: Array<FieldIssue>;
        /**
         * Per-field non-blocking warnings of the row (e.g. recipient not found in the AEAT census). Empty when there are none.
         */
        warnings: Array<FieldIssue>;
    }>;
    /**
     * Rows that could not be created (create mode, `dry_run=false`). Each item carries the 0-based `index`, an `error_code`, a Spanish `error_message` and the per-field `errors[]`. Empty in validate-only mode.
     */
    failures: Array<{
        /**
         * 0-based position of the row within the batch.
         */
        index: number;
        /**
         * Machine-readable error code from the v1 error catalog (stable across languages).
         */
        error_code: string;
        /**
         * Human-readable reason for the failure, in Spanish.
         */
        error_message: string;
        /**
         * Per-field blocking issues that made the row invalid.
         */
        errors?: Array<FieldIssue>;
    }>;
};

