    object: 'contact_stats';
    total: number;
    customer: number;
    supplier: number;
    unassigned: number;
    lead: number;
    active_lead: number;
    inactive_lead: number;
    dual_role: number;
    person: number;
    company: number;
    active_customer: number;
    inactive_customer: number;
