/**
 * User
 *
 * A member of your company: someone tasks can be assigned to.
 */
export type User = {
    /**
     * UUID of the user.
     */
    id: string;
    /**
     * Stripe-like discriminator. Always `user` for this resource.
     */
    object: 'user';
    name: string;
    email: string;
    /**
     * Initials shown in the avatar.
     */
    initials: string;
    /**
     * Avatar color, stable per user.
     */
    avatar_color: string;
};

/**
 * UserList
 *
 * Page of users (`{ data, has_more, next_cursor }`).
 */
export type UserList = {
    data: Array<User>;
    /**
     * `true` when there are more objects after this page.
     */
    has_more: boolean;
    /**
     * Value to pass as `starting_after` to get the next page (the `id` of the last object), or `null` when `has_more` is `false`.
     */
    next_cursor: string | null;
};

/**
 * VeriFactuActivity
 *
 * An event in the activity timeline of a VeriFactu record (creation, transmission attempts, AEAT acceptance/rejection).
 */
export type VeriFactuActivity = {
    object: 'verifactu_activity';
    /**
     * Domain event type (e.g. `verifactu.record_created`, `verifactu.transmission_accepted`).
     */
    event_type: string;
    /**
     * Human-readable description of the event in Spanish.
     */
    description: string;
    /**
     * Event metadata. Internal identifiers (PKs), `huella` and certificate secrets are stripped; `*_uuid` values are preserved.
     */
    metadata: {
        [key: string]: unknown;
    };
    /**
     * Actor that originated the event. `{type:"user",...}` for an internal user, `{type:"api_key",...}` when performed via the public v1 API, or `null` when the event is system-generated (scheduler, periodic sweep) with no attributable actor.
     */
    performed_by: {
        /**
         * Type of actor that originated the event: `user` for a human in the internal app, `api_key` for an action performed through the public v1 API.
         */
        type: 'user' | 'api_key';
        /**
         * UUID v7 of the actor: the user when `type=user`, or the API key when `type=api_key`.
         */
        id: string;
        /**
         * Actor name at the time of the event: the user name or the API key name. `null` if it could not be resolved.
         */
        name: string | null;
    } | null;
    /**
     * When the event occurred (ISO 8601).
     */
    created_at: string;
};

/**
 * VeriFactuConfig
 *
 * VeriFactu configuration of your company (mode, environment, enrollment). Returned by `GET /v1/companies/{company}/verifactu/config` and `PATCH /v1/companies/{company}/verifactu/settings`. The certificate password is never exposed.
 */
export type VeriFactuConfig = {
    object: 'verifactu_config';
    /**
     * Indicates whether VeriFactu is enabled for the company.
     */
    enabled: boolean;
    /**
     * VeriFactu operation mode.
     */
    mode: string;
    /**
     * Indicates whether transmissions to AEAT are sent automatically.
     */
    auto_transmit: boolean;
    /**
     * AEAT environment (`sandbox` / `production`).
     */
    environment: string;
    /**
     * Notification emails for VeriFactu events.
     */
    notification_emails: Array<string>;
    /**
     * Date until which the mode change is locked, or `null` if not locked.
     */
    is_locked_until: string | null;
    /**
     * Whether there is an active certificate configured.
     */
    has_active_certificate: boolean;
    /**
     * UUID v7 of the active certificate, or `null` if there is none.
     */
    active_certificate_id: string | null;
    updated_at: string | null;
    /**
     * Who remits your records to AEAT: `own_certificate` (the default: your own certificate), `social_collaborator` (Factuarea remits with its certificate as social collaborator, annex I of the Resolution of 18-12-2024) or `power_of_attorney` (Factuarea remits under a power of attorney registered with AEAT). A third-party mode requires an active representation of the kind it asks for (`POST /v1/companies/{company}/verifactu/representation`); change it with `PATCH /v1/companies/{company}/verifactu/settings`.
     */
    remission_mode: 'own_certificate' | 'social_collaborator' | 'power_of_attorney';
    /**
     * Whether the company has a current representation that has NOT expired — the one that enables third-party remission — regardless of the mode. A representation that has expired keeps `active_representation_id` and `_kind` but this field is `false` (see `active_representation_is_expired`).
     */
    has_active_representation: boolean;
    /**
     * UUID v7 of the current (not revoked) representation, even if it has expired, or `null` if there is none.
     */
    active_representation_id: string | null;
    /**
     * Kind of the current (not revoked) representation, even if it has expired, or `null` if there is none.
     */
    active_representation_kind: 'social_collaboration_annex_i' | 'aeat_power_of_attorney' | null;
    /**
     * Last day of validity (YYYY-MM-DD, Europe/Madrid) of the current representation, or `null` when there is none or it does not expire.
     */
    active_representation_valid_until: string | null;
    /**
     * Whether the current representation has expired. `false` when there is none.
     */
    active_representation_is_expired: boolean;
    /**
     * Whether this instance offers the `social_collaborator` remission mode (the social-collaboration agreement with AEAT is in force). It is a fact of the instance, the same for every company: while it is `false`, `PATCH /v1/companies/{company}/verifactu/settings` with that mode returns 422 `social_collaborator_unavailable` and `power_of_attorney` covers the same use case.
     */
    social_collaborator_available: boolean;
    /**
     * State of the certificate that the remission would present given `remission_mode`: yours in `own_certificate`, the one of Factuarea in a third-party mode. `valid`: usable; `invalid`: configured but expired, revoked or for another tax ID; `not_configured`: there is none. The certificate of Factuarea never exposes its holder, tax ID, serial number or identifier.
     */
    presenter_certificate_status: 'valid' | 'invalid' | 'not_configured';
};

/**
 * VeriFactuEvent
 *
 * A VeriFactu SIF event (Art. 8.1.b): a transmission/retry/AEAT-response entry of the system. The hash chain is never exposed here.
 */
export type VeriFactuEvent = {
    /**
     * UUID v7 of the event.
     */
    id: string;
    object: 'verifactu_event';
    /**
     * SIF event type.
     */
    event_type: string;
    /**
     * Non-PII descriptive data of the event (label, description, CSV, error code/message). Empty object `{}` when there is no data. Sanitized via MetadataSanitizer.
     */
    event_data: {
        [key: string]: unknown;
    };
    /**
     * AEAT status of the event.
     */
    status: string;
    /**
     * When the event was generated.
     */
    occurred_at: string;
    created_at: string;
    /**
     * Number of transmission attempts made.
     */
    retry_count: number;
    /**
     * Maximum number of retries configured.
     */
    max_retries: number;
};

/**
 * VeriFactuEventSummary
 *
 * Aggregated summary of the VeriFactu events of the company: total and breakdown by type and by status. Returned by `GET /v1/companies/{company}/verifactu/events/summary`.
 */
export type VeriFactuEventSummary = {
    object: 'verifactu_event_summary';
    /**
     * Total number of recorded events.
     */
    total_events: number;
    /**
     * Event count by type.
     */
    events_by_type: {
        [key: string]: number;
    };
    /**
     * Event count by AEAT status.
     */
    events_by_status: {
        [key: string]: number;
    };
    /**
     * Date of the last event, or `null` if there is none.
     */
    last_event_at: string | null;
};

/**
 * VeriFactuRecord
 *
 * A VeriFactu (Spanish AEAT SIF) record (alta/anulación) associated with an invoice. Includes the hash chain (`huella`), AEAT CSV and transmission status for reconciliation.
 */
export type VeriFactuRecord = {
    /**
     * UUID v7 of the VeriFactu record.
     */
    id: string;
    object: 'verifactu_record';
    /**
     * Record type: `alta` (registration) or `anulacion` (cancellation).
     */
    type: string;
    /**
     * AEAT invoice type (F1, F2, F3, R1-R5, …).
     */
    invoice_type: string;
    /**
     * Number of the associated invoice.
     */
    invoice_number: string;
    /**
     * Record date.
     */
    date: string;
    /**
     * Total amount of the associated invoice.
     */
    amount: string;
    /**
     * Transmission status (pending, submitted, accepted, rejected, error).
     */
    status: string;
    /**
     * Chained SHA-256 fingerprint of the record (VeriFactu fingerprint).
     */
    huella: string;
    /**
     * Submission identifier assigned by AEAT (column `aeat_submission_id`). `null` until AEAT returns it. Never the internal PK of the record.
     */
    aeat_submission_id: string | null;
    /**
     * Secure Verification Code (Código Seguro de Verificación) returned by AEAT on acceptance. `null` until AEAT assigns it.
     */
    aeat_csv: string | null;
    /**
     * AEAT environment (`sandbox` / `production`).
     */
    environment: string;
    /**
     * ISO 8601 date of the last transmission that reached AEAT. `null` in PENDING/REJECTED/ERROR states.
     */
    transmitted_at: string | null;
    /**
     * Whether the invoice is simplified (F2).
     */
    is_simplificada: boolean;
    /**
     * Whether it substitutes one or more simplified invoices (F3).
     */
    is_substitute_for_simplified: boolean;
    created_at: string;
    /**
     * Error code of the last AEAT rejection or failure (for example `1110` or `4112`), the internal code of a record that is stopped (`MISSING_CERTIFICATE`, `MISSING_REPRESENTATION`, `SYSTEM_CERTIFICATE_UNAVAILABLE`), `SCHEMA_INVALID` on a `rejected` record that was never sent because it does not meet the AEAT XML schema (fix it with a subsanation), or the warning code of a record accepted with errors; `null` when there is none. Without it you cannot tell a `4112` (presenter not enabled by AEAT) from a network failure.
     */
    aeat_error_code: string | null;
    /**
     * Whether the record is BLOCKED: it is in `error` with NO automatic retry, so it does not go out again until someone reactivates it (fix the cause, then `POST /v1/companies/{company}/verifactu/records/retry-blocked`, or `POST /v1/companies/{company}/verifactu/records/{record}/retry` one by one), and it holds back the rest of the chain of the company. `false` for a record that retries by itself, with a backoff of at most one hour (art. 16.4 of Order HAC/1177/2024).
     */
    is_blocked: boolean;
    /**
     * Why the remission of the record is stopped, or `null`. `MISSING_CERTIFICATE`: your company has no usable certificate (missing, expired, revoked or for another tax ID). `MISSING_REPRESENTATION`: the remission mode is a third-party one and there is no current representation of the kind it asks for. `PRESENTER_NOT_ENABLED`: AEAT says the presenter is not enabled (`4112` or `3003`). `SUBMISSION_REJECTED`: AEAT rejected the submission for a client-side fault. These four need an action from you and make `is_blocked` true. `SYSTEM_CERTIFICATE_UNAVAILABLE`: the certificate of Factuarea that remits in the third-party modes is not available; it is on our side, does NOT block (`is_blocked` stays `false`) and the record retries by itself.
     */
    block_reason: 'MISSING_CERTIFICATE' | 'MISSING_REPRESENTATION' | 'SYSTEM_CERTIFICATE_UNAVAILABLE' | 'PRESENTER_NOT_ENABLED' | 'SUBMISSION_REJECTED' | null;
    /**
     * Whether the record admits `POST /v1/companies/{company}/verifactu/records/{record}/subsanar`: an `alta` that is ACCEPTED (or accepted with errors) or REJECTED by AEAT and is the last one of its invoice, which has not been annulled. It is the very rule that endpoint applies, so `true` guarantees it will not refuse the record by its state; whether there is something to correct and whether it changes a field of the hash (`requires_annulment`) is only known when you subsanar.
     */
    can_subsanar: boolean;
    /**
     * For a record AEAT accepted with errors (`status` `accepted` with an `aeat_error_code`), whether AEAT requires a subsanation of that admissible error: every `2xxx` code does except `2004` (FechaHoraHusoGenRegistro) and `2009` (ClaveRegimen with IPSI), which AEAT exempts (AEAT «Validaciones» v1.2.2, §4.3.1). `false` for a warning that is not an AEAT code (`duplicate_annulled`: review the invoice instead). `null` when the record is not accepted with a warning.
     */
    aeat_warning_requires_subsanation: boolean | null;
};

/**
 * VeriFactuStats
 *
 * Aggregated summary of the VeriFactu records of the authenticated company: counts by status and breakdown by type. Returned by `GET /v1/companies/{company}/verifactu/stats`.
 */
export type VeriFactuStats = {
    object: 'verifactu_stats';
    /**
     * Total number of VeriFactu records.
     */
    total_records: number;
    /**
     * Records pending transmission.
     */
    pending: number;
    /**
     * Records submitted to AEAT (without a final response yet).
     */
    submitted: number;
    /**
     * Records accepted by AEAT.
     */
    accepted: number;
    /**
     * Records rejected by AEAT.
     */
    rejected: number;
    /**
     * Records in error status.
     */
    error: number;
    /**
     * Count by record type (registration/cancellation).
     */
    by_record_type: {
        [key: string]: number;
    };
    /**
     * Count by AEAT invoice type (F1, F2, F3, …).
     */
    by_invoice_type: {
        [key: string]: number;
    };
    /**
     * Date of the last transmission to AEAT, or `null` if there is none.
     */
    last_transmission_at: string | null;
    /**
     * Records still waiting to be remitted to AEAT: `pending` (or without a state yet), `error` of ANY kind (those that retry by themselves and the blocked ones), `submitted` (in flight, or orphaned until the next sweep) and `rejected` records that have already been subsanados. NOT counted: `accepted`, `rejected` records still waiting for your correction, and sandbox (test mode) companies. The query filters never affect it. Art. 16 of Order HAC/1177/2024 requires the taxpayer to see how many records are pending.
     */
    pending_incident_count: number;
    /**
     * Of the pending records, the BLOCKED ones: `error` with NO automatic retry (missing certificate or representation, presenter not enabled by AEAT, or a client-side rejection). They do not go out until someone reactivates them (`POST /v1/companies/{company}/verifactu/records/retry-blocked`) and they hold back the chain of the company. It is a subset of `pending_incident_count`; the query filters never affect it.
     */
    blocked_incident_count: number;
    /**
     * Generation timestamp of the oldest of the pending records counted by `pending_incident_count`, or `null` when there is none. The query filters never affect it.
     */
    oldest_pending_at: string | null;
};

